export function createClient(transport) {
  return {
    getOrder: (id) => transport.get(`/orders/${id}?include=zone`),
    getZone: (id) => transport.get(`/zones/${id}`),
    setPickup: (id, time) => transport.put(`/orders/${id}/pickup`, { time }),
    setSlot: (id, slot) => transport.put(`/orders/${id}/slot`, { slot }),
  };
}
